          M.bell(E, t + 0.01, [NOTE.D5, NOTE.A4, NOTE.Fs4, NOTE.E4, NOTE.D4][Math.min(4, place3 - 1)], { gain: place3 === 1 ? 0.45 : 0.28, dec: 0.9 });
