      /**
       * getKey
       */
      getKey(i, j) {
        if (j < i) {
          const temp = j;
          j = i;
          i = temp;
        }
        return i << 16 | j;
      }
      /**
       * set
       */
      set(i, j) {
        const key = this.getKey(i, j);
        const current = this.current;
        let index = 0;
        while (key > current[index]) {
          index++;
        }
        if (key === current[index]) {
          return;
        }
        for (let j2 = current.length - 1; j2 >= index; j2--) {
          current[j2 + 1] = current[j2];
        }
        current[index] = key;
      }
